use std::fs

fn find(names: Vec<string>, name: string) -> int {
    let n: int = names.len() as int
    let mut i: int = 0
    while i < n {
        if names[i] == name {
            return i
        }
        i += 1
    }
    -1
}

fn amount(s: string) -> int {
    s.parse::<int>().unwrap_or(0)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut names: Vec<string> = []
    let mut bals: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|x| x.to_string()).collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "open" {
            let amt = amount(parts[2])
            if amt < 0 {
                println("error: invalid amount")
            } else if find(names, parts[1]) >= 0 {
                println("error: duplicate account")
            } else {
                names.push(parts[1])
                bals.push(amt)
                println("ok")
            }
        } else if cmd == "balance" {
            let i = find(names, parts[1])
            if i < 0 {
                println("error: unknown account ${parts[1]}")
            } else {
                println("${bals[i]}")
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            let amt = amount(parts[2])
            let i = find(names, parts[1])
            if amt <= 0 {
                println("error: invalid amount")
            } else if i < 0 {
                println("error: unknown account ${parts[1]}")
            } else if cmd == "deposit" {
                bals[i] = bals[i] + amt
                println("ok")
            } else if bals[i] < amt {
                println("error: insufficient funds")
            } else {
                bals[i] = bals[i] - amt
                println("ok")
            }
        } else if cmd == "transfer" {
            let amt = amount(parts[3])
            let f = find(names, parts[1])
            let t = find(names, parts[2])
            if amt <= 0 {
                println("error: invalid amount")
            } else if f < 0 {
                println("error: unknown account ${parts[1]}")
            } else if t < 0 {
                println("error: unknown account ${parts[2]}")
            } else if f == t {
                println("error: same account")
            } else if bals[f] < amt {
                println("error: insufficient funds")
            } else {
                bals[f] = bals[f] - amt
                bals[t] = bals[t] + amt
                println("ok")
            }
        }
    }
    let mut sorted: Vec<string> = names
    sorted.sort()
    for nm in sorted {
        let i = find(names, nm)
        println("${nm} ${bals[i]}")
    }
}

